/// Per-frame palette from `palette:` in the YAML. 256 words a frame --
/// the cheapest animation available, and flat in wall size.
pub fn palette_hello(ctx: &Ctx, i: usize) -> u32 {
    let _ = (&ctx, i);
    let f = ctx.frame as usize;
    match i {
        // The white ramp breathes. Nothing is redrawn to make this happen.
        16..=31 => {
            let cov = (i - 16) as u32;
            let lift = 150 + (sin64(f / 8) + 256) as u32 * 100 / 512;
            rgb((lift * cov / 15) as u8, (lift * cov / 15) as u8, (lift * cov / 15) as u8)
        }
        _ => crate::program::palette_default(i),
    }
}

