/// Generated from panels/ticker.yaml -- edit the YAML, not this.
///
/// ONE function per row, in two halves: a prologue of everything that
/// depends on y but not x, then the pixel loop. That split is the whole
/// reason a program is affordable, and it is why the prologue is inlined
/// here rather than living in a helper -- a `lambda` widget's own `row:`
/// block is spliced into it, and its locals have to be visible to the
/// loop body below.
///
/// The band test, the `when:` guard, the value lookup and the centring
/// width() all depend only on the row, but were once evaluated inside the
/// pixel loop, per widget, for all 16384 pixels. `ctx.val()` is a linear
/// scan of the value table, and a four-page program asks `page == 'N'` in
/// every widget, so a pixel paid for ~24 of them. Measured on
/// dashboard-home: 20268 cycles per pixel, against 11 for a bare store.
pub fn render_ticker(ctx: &Ctx, y: usize, x0: usize, row: &mut [u32]) {
    let _ = (&ctx, y, x0);
    #[allow(non_snake_case)] let FONT_LABEL = &FONT_DEJAVUSANS_13;
    #[allow(non_upper_case_globals)] const FONT_LABEL_LH: usize = FONT_DEJAVUSANS_13_LH;
    #[allow(non_snake_case)] let FONT_TICK = &FONT_DEJAVUSANSMONOBOLD_26;
    #[allow(non_upper_case_globals)] const FONT_TICK_LH: usize = FONT_DEJAVUSANSMONOBOLD_26_LH;
    // value 'hhmm'
    let g_0 = y >= 44 && y < 44 + FONT_TICK_LH;
    let (s_0, o_0, e_0) = if g_0 {
        let s = ctx.val("hhmm");
        let tw = FONT_TICK.width(s);
        let ox = if ctx.w > tw { (ctx.w - tw) / 2 } else { 2 };
        (s, ox, ox + tw + 4)
    } else { ("", 0usize, 0usize) };
    let mut b_1 = [0u8; 48];
    // value 'temp'
    let g_1 = y >= 72 && y < 72 + FONT_LABEL_LH;
    let (s_1, o_1, e_1) = if g_1 {
        let s = join3(&mut b_1, "OUTSIDE ", ctx.val("temp"), "°");
        let tw = FONT_LABEL.width(s);
        let ox = if ctx.w > tw { (ctx.w - tw) / 2 } else { 2 };
        (s, ox, ox + tw + 4)
    } else { ("", 0usize, 0usize) };
    // ---- lambda row: prologue (verbatim) ----
    let top_row = y >= 8 && y < 42;
    let bot_row = y >= 88 && y < 122;
    let ring_row = y < 3 || y >= ctx.h - 3;
    let ybulb = y >> 3;
    for (i, p) in row.iter_mut().enumerate() {
        let x = x0 + i;
        *p = (|| -> u32 {
            if g_0 && x >= o_0 && x < e_0 {
                if let Some(c) = FONT_TICK.cover_at(s_0, x, y, o_0, 44) { return (RAMP_WHITE + c) as u32; }
            }
            if g_1 && x >= o_1 && x < e_1 {
                if let Some(c) = FONT_LABEL.cover_at(s_1, x, y, o_1, 72) { return (RAMP_BRASS + c) as u32; }
            }
            // ---- lambda (verbatim from the YAML) ----
            if let Some(i) = (|| -> Option<u8> {
                // Built only when a value actually LANDS -- about once every ten
                // seconds, not once per frame. Padded to a power-of-two length so
                // cover_scroll's message index is a mask rather than a third software
                // division; riscv32i has no divide instruction.
                fn top(ctx: &Ctx, m: &mut Msg) {
                    use core::fmt::Write;
                    // Padding is for a CONSTANT PERIOD, not for length: cover_scroll
                    // wraps modulo len*advance, so a message that changed length would
                    // make the tape jump. But pad far past the text and the padding is
                    // what you see -- 38 characters padded to 64 left 26 spaces, a
                    // 416px gap in a 1024px period, so the tape read as empty for
                    // fifteen seconds out of every thirty-six. Fill the period.
                    let _ = write!(m, "*** DASHBOARD NEW YORK *** OUTSIDE {:>3.3}F *** {:<11.11} *** ",
                                   ctx.val("temp"), ctx.val("cond"));
                    m.pad_to(64);
                }
                fn bot(ctx: &Ctx, m: &mut Msg) {
                    use core::fmt::Write;
                    let _ = write!(m, "+++ HOUSE LOAD {:>6.6} kW +++ THE TIME IS {:>5.5} +++ ON AIR +++ ",
                                   ctx.val("power"), ctx.val("hhmm"));
                    m.pad_to(64);
                }
                
                if top_row {
                    if let Some(c) = scroll_message(ctx, &FONT_TICK, top, x, y, 10, 1, RAMP_WHITE) {
                        return Some(c);
                    }
                    return Some(RAMP_SLATE + ((y - 8) * 15 / 34) as u8);
                }
                if bot_row {
                    if let Some(c) = scroll_message_rev(ctx, &FONT_TICK, bot, x, y, 90, 1, RAMP_WHITE) {
                        return Some(c);
                    }
                    return Some(RAMP_SLATE + ((121 - y) * 15 / 34) as u8);
                }
                
                // The bulb ring. A pixel takes the index of the BULB it belongs to and
                // the palette does the chasing -- so the frame is alive for no writes.
                if ring_row || x < 3 || x >= ctx.w - 3 {
                    return Some(RAMP_BULB + (((x >> 3) + ybulb) & 15) as u8);
                }
                
                // THE ZOOM, and it costs nothing.
                //
                // Each pixel takes the index of the RING it sits on -- Chebyshev
                // distance from the centre, which is two abs_diffs and a max. A squared
                // radius would be two multiplies and a compare per pixel; this is three
                // single-cycle operations and looks better here anyway. Rotating those entries in
                // the palette makes the rings rush outward, and dropping their
                // brightness together makes the whole sign flash.
                //
                // So the attract sequence -- rings zooming, colour cycling, the big
                // strobe every eight seconds -- is 256 words a frame and NOT ONE pixel
                // write. That is the argument for program mode in one line.
                let d = x.abs_diff(ctx.w / 2).max(y.abs_diff(ctx.h / 2));
                Some(RAINBOW + ((d << 2) & 127) as u8)
            })() { return i as u32; }
            BG as u32
        })();
    }
}

/// Scroll bands from `scroll:` in the YAML: (y0, y1, speed, rightward).
pub const SCROLL_TICKER: &[(usize, usize, usize, bool)] = &[
    (8, 42, 1, false),
    (88, 122, 1, true),
];

/// Rows that change every frame, from `display.dynamic` in the YAML.
pub const DYNAMIC_TICKER: Option<(usize, usize)> = Some((0, 0));

/// Per-frame palette from `palette:` in the YAML. 256 words a frame --
/// the cheapest animation available, and flat in wall size.
pub fn palette_ticker(ctx: &Ctx, i: usize) -> u32 {
    let _ = (&ctx, i);
    let f = ctx.frame as usize;
    // THE BEAT. ~8 seconds at 30 fps: a long calm stretch, then a two-second
    // blast. Derived from the frame counter, so it needs no state and survives a
    // program restart mid-cycle.
    let beat = f % 240;
    let blast = beat >= 180;
    // How hard the blast hits. NOT 255: a HUB75 module at this pitch is painfully
    // bright at full scale, and the gateware applies gamma downstream so the top
    // of the range is where most of the perceived output lives. ~60% reads as a
    // bright flash across a room without being unpleasant to sit near.
    const HOT: u32 = 150;
    // And it strobes on one frame in four rather than two, so it reads as a
    // flicker rather than a stutter.
    let strobe = f & 3 == 0;
    // Six-segment hue wheel, 0..127 -> rgb. No float and no divide beyond the
    // constants; this runs 256 times a frame, not once per pixel.
    fn wheel(t: usize) -> (u32, u32, u32) {
        let t = t & 127;
        let seg = t * 6 / 128;
        let k = (((t * 6) % 128) * 255 / 128) as u32;
        match seg {
            0 => (255, k, 0),
            1 => (255 - k, 255, 0),
            2 => (0, 255, k),
            3 => (0, 255 - k, 255),
            4 => (k, 0, 255),
            _ => (255, 0, 255 - k),
        }
    }
    match i {
        // 16..31 -- tape text AND the clock. Hue runs ALONG the run, so the
        // colour travels through the letters while the letters travel past.
        16..=31 => {
            let cov = (i - 16) as u32;
            // During the blast the type goes hard white and strobes with the
            // field, so the whole sign pulses as one thing.
            if blast && strobe {
                // The type stays a little hotter than the rest -- it is what the
                // eye lands on -- but still well under full scale.
                let w = HOT + 40;
                rgb((w * cov / 15) as u8, (w * cov / 15) as u8, (w * cov / 15) as u8)
            } else {
                let (r, g, b) = wheel((i - 16) * 5 + f * if blast { 12 } else { 3 });
                rgb((r * cov / 15) as u8, (g * cov / 15) as u8, (b * cov / 15) as u8)
            }
        }
        // 32..47 -- the temperature, pulsing white-hot to amber.
        32..=47 => {
            let cov = (i - 32) as u32;
            let beat = (176 + sin64(f / 2) * 80 / 256) as u32;
            rgb((beat * cov / 15) as u8, ((beat * 3 / 4) * cov / 15) as u8, ((beat / 3) * cov / 15) as u8)
        }
        // 48..63 -- the tape grounds, breathing. The pixels holding these
        // indices are never rewritten, so this motion is free.
        48..=63 => {
            let d = (i - 48) as u32;
            // The grounds fire with everything else, so the blast is the WHOLE
            // sign going off rather than a bright patch in the middle of it.
            if blast && strobe {
                rgb((HOT * d / 15) as u8, (HOT * d / 15) as u8, (HOT * d / 15) as u8)
            } else {
                let pulse = 30 + (sin64(f / 4 + (i - 48)) + 256) as u32 * 50 / 512;
                rgb((pulse * d / 46) as u8, (pulse * d / 30) as u8, (pulse * d / 20) as u8)
            }
        }
        // 64..191 -- the rings. THE ATTRACT SEQUENCE LIVES HERE.
        //
        // An eight-second beat: seven seconds of rings rushing outward under the
        // clock, then a two-second BLAST where they accelerate, saturate and
        // strobe. None of it writes a pixel.
        64..=191 => {
            let t = i - 64;
            if blast {
                // Rings rush four times faster and run at full brightness, with
                // the whole field flashing to white on alternate frames.
                let (r, g, b) = wheel(t + f * 8);
                if strobe { rgb(HOT as u8, HOT as u8, HOT as u8) }
                else { rgb((r * 3 / 5) as u8, (g * 3 / 5) as u8, (b * 3 / 5) as u8) }
            } else {
                // Held well down the rest of the time so the clock reads.
                let (r, g, b) = wheel(t + f * 2);
                let k = 4 + (sin64(f / 6) + 256) as u32 * 4 / 512;
                rgb((r / k) as u8, (g / k) as u8, (b / k) as u8)
            }
        }
        // 208..223 -- theatre bulbs. A bright group of three chases round the
        // sixteen phases; the rest glow dim, and the whole ring drifts in hue.
        208..=223 => {
            // Chasing normally; during the blast every bulb fires at once, on
            // alternate frames, like a theatre frame being flashed.
            let ph = (i - 208 + f / if blast { 1 } else { 2 }) & 15;
            let (r, g, b) = wheel((i - 208) * 8 + f * 4);
            if blast {
                if strobe { rgb(HOT as u8, HOT as u8, HOT as u8) }
                else { rgb((r * 3 / 5) as u8, (g * 3 / 5) as u8, (b * 3 / 5) as u8) }
            }
            // The lit bulbs ring the whole frame and are on all the time, so
            // they are what the room actually sees. Held to ~70% -- at full
            // scale they were the brightest thing on the panel by a distance.
            else if ph < 3 { rgb((r * 7 / 10) as u8, (g * 7 / 10) as u8, (b * 7 / 10) as u8) }
            else { rgb((r / 7) as u8, (g / 7) as u8, (b / 7) as u8) }
        }
        _ => crate::program::palette_default(i),
    }
}

/// Generated from panels/timessquare.yaml -- edit the YAML, not this.
///
/// ONE function per row, in two halves: a prologue of everything that
/// depends on y but not x, then the pixel loop. That split is the whole
/// reason a program is affordable, and it is why the prologue is inlined
/// here rather than living in a helper -- a `lambda` widget's own `row:`
/// block is spliced into it, and its locals have to be visible to the
/// loop body below.
///
/// The band test, the `when:` guard, the value lookup and the centring
/// width() all depend only on the row, but were once evaluated inside the
/// pixel loop, per widget, for all 16384 pixels. `ctx.val()` is a linear
/// scan of the value table, and a four-page program asks `page == 'N'` in
/// every widget, so a pixel paid for ~24 of them. Measured on
/// dashboard-home: 20268 cycles per pixel, against 11 for a bare store.
pub fn render_timessquare(ctx: &Ctx, y: usize, x0: usize, row: &mut [u32]) {
    let _ = (&ctx, y, x0);
    #[allow(non_snake_case)] let FONT_TICK = &FONT_DEJAVUSANSMONOBOLD_26;
    #[allow(non_upper_case_globals)] const FONT_TICK_LH: usize = FONT_DEJAVUSANSMONOBOLD_26_LH;
    #[allow(non_snake_case)] let ICON_STAR = &ICON_STAR_26;
    // ---- lambda row: prologue (verbatim) ----
    // Everything here happens 128 times a frame instead of 16384.
    let f = ctx.frame as usize;
    let plasma_row = PlasmaRow::new(ctx, y);
    let spin = f / 2;
    let tape_top = y >= 6 && y < 40;
    let tape_bot = y >= 90 && y < 124;
    let star_row = y.abs_diff(ctx.h / 2) <= 21;
    // The border and the stale marker only ever ink the outside. Deciding
    // that once per row means ~14000 pixels a frame stop making two calls
    // apiece to be told "not here".
    let edge_row = y < 3 || y >= ctx.h - 3;
    let stale_row = y < 6 && ctx.stale_ms() > 30_000;
    let ground_top = RAMP_SLATE + ((y.saturating_sub(6)) * 15 / 34) as u8;
    let ground_bot = RAMP_SLATE + ((123usize.saturating_sub(y)) * 15 / 34) as u8;
    for (i, p) in row.iter_mut().enumerate() {
        let x = x0 + i;
        *p = (|| -> u32 {
            // ---- lambda (verbatim from the YAML) ----
            if let Some(i) = (|| -> Option<u8> {
                fn top(ctx: &Ctx, m: &mut Msg) {
                    use core::fmt::Write;
                    let _ = write!(
                        m, "*** DASHBOARD NEW YORK *** OUTSIDE {:>3.3}F *** {:<11.11} *** ",
                        ctx.val("temp"), ctx.val("cond"),
                    );
                    // 59 characters into a 64 period. Padding sets the PERIOD, so it
                    // must be the next power of two ABOVE the text, not far above it:
                    // pad far past and the padding is what you see. This tape was 62
                    // characters padded to 128, which is 66 blank ones -- the tape read
                    // as empty most of the time.
                    m.pad_to(64);
                }
                fn bot(ctx: &Ctx, m: &mut Msg) {
                    use core::fmt::Write;
                    let _ = write!(
                        m, "+++ DOORS {:>2.2} +++ WINDOWS {:>2.2} +++ GARAGE {:>2.2} +++ UNLOCKED {:>2.2} +++ ",
                        ctx.val("doors"), ctx.val("windows"), ctx.val("garage"), ctx.val("unlocked"),
                    );
                    m.pad_to(64);
                }
                
                // The tapes are SHIFTED, not redrawn, so they may contain only the text
                // and a ground that depends on y alone -- no sparkle, no plasma, or the
                // shift would smear it along with the letters. A shift moves pixels
                // along a row, so anything constant in x survives untouched: that is
                // how a shifted tape still gets a moving background, since the ground
                // is a palette INDEX and the palette hook animates it for no writes.
                if tape_top {
                    if let Some(c) = scroll_message(ctx, &FONT_TICK, top, x, y, 8, 1, RAMP_WHITE) {
                        return Some(c);
                    }
                    return Some(ground_top);
                }
                if tape_bot {
                    if let Some(c) = scroll_message_rev(ctx, &FONT_TICK, bot, x, y, 92, 1, RAMP_WHITE) {
                        return Some(c);
                    }
                    return Some(ground_bot);
                }
                
                // The thing a streamed panel structurally cannot do: when the host dies
                // it keeps showing a frame that looks perfectly correct. This says so.
                if stale_row && x >= ctx.w - 6 { return Some(ALERT); }
                
                if let Some(c) = sparkle(ctx, x, y, 17, RAMP_WHITE) { return Some(c); }
                if edge_row || x < 3 || x >= ctx.w - 3 {
                    if let Some(c) = border_chase(ctx, x, y, 3, 3) { return Some(c); }
                }
                if star_row {
                    if let Some(c) = sprite_rotated(&ICON_STAR, x, y, ctx.w / 2, ctx.h / 2, spin, RAMP_WHITE) {
                        return Some(c);
                    }
                }
                Some(plasma_row.at(x))
            })() { return i as u32; }
            BG as u32
        })();
    }
}

/// Scroll bands from `scroll:` in the YAML: (y0, y1, speed, rightward).
pub const SCROLL_TIMESSQUARE: &[(usize, usize, usize, bool)] = &[
    (6, 40, 1, false),
    (90, 124, 1, true),
];

/// No `display.dynamic` declared: every row is treated as changing.
pub const DYNAMIC_TIMESSQUARE: Option<(usize, usize)> = None;

/// Per-frame palette from `palette:` in the YAML. 256 words a frame --
/// the cheapest animation available, and flat in wall size.
pub fn palette_timessquare(ctx: &Ctx, i: usize) -> u32 {
    let _ = (&ctx, i);
    let f = ctx.frame as usize;
    match i {
        0 => rgb(0, 0, 0),
        1..=3 => rgb(0, 0, 0),
        16..=31 => {
            let cov = (i - 16) as u32;
            let t = ((i - 16) * 6 + f * 4) & 127;
            let seg = t * 6 / 128;
            let k = (((t * 6) % 128) * 255 / 128) as u32;
            let (r, g, b) = match seg {
                0 => (255, k, 0),
                1 => (255 - k, 255, 0),
                2 => (0, 255, k),
                3 => (0, 255 - k, 255),
                4 => (k, 0, 255),
                _ => (255, 0, 255 - k),
            };
            rgb((r * cov / 15) as u8, (g * cov / 15) as u8, (b * cov / 15) as u8)
        }
        48..=63 => {
            let d = (i - 48) as u32;
            let pulse = 40 + (sin64(f / 3 + (i - 48) * 2) + 256) as u32 * 60 / 512;
            rgb((pulse * d / 40) as u8, (pulse * d / 26) as u8, (pulse * d / 18) as u8)
        }
        _ => crate::program::palette_default(i),
    }
}

/// Programs by name, so `mode: program` can select one at runtime
/// without a per-panel firmware -- marquee cannot do that (TODO item 8).
/// Every program in this firmware. One firmware carries them all and
/// the config picks which runs -- marquee cannot do per-panel firmware.
pub static PROGRAMS: [Program; 6] = [
    Program { name: "hello", row: render_hello, palette_static: false, dynamic: DYNAMIC_HELLO, scroll: SCROLL_HELLO, palette: Some(palette_hello) },
    Program { name: "railboard", row: render_railboard, palette_static: true, dynamic: DYNAMIC_RAILBOARD, scroll: SCROLL_RAILBOARD, palette: Some(palette_railboard) },
    Program { name: "dashboard-home", row: render_dashboard_home, palette_static: true, dynamic: DYNAMIC_DASHBOARD_HOME, scroll: SCROLL_DASHBOARD_HOME, palette: Some(palette_dashboard_home) },
    Program { name: "blank", row: render_blank, palette_static: false, dynamic: DYNAMIC_BLANK, scroll: SCROLL_BLANK, palette: None },
    Program { name: "ticker", row: render_ticker, palette_static: false, dynamic: DYNAMIC_TICKER, scroll: SCROLL_TICKER, palette: Some(palette_ticker) },
    Program { name: "timessquare", row: render_timessquare, palette_static: false, dynamic: DYNAMIC_TIMESSQUARE, scroll: SCROLL_TIMESSQUARE, palette: Some(palette_timessquare) },
];

pub fn by_name(n: &str) -> Option<&'static Program> {
    PROGRAMS.iter().find(|p| p.name == n)
}
